package main

import (
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"time"
)

// Request represents the incoming JSON request payload.
type Request struct {
	Name  string `json:"name"`
	Email string `json:"email"`
	Age   int    `json:"age"`
}

// Response represents the outgoing JSON response payload.
type Response struct {
	Status  string `json:"status"`
	Message string `json:"message"`
}

// Handler is the main HTTP handler function.
func Handler(w http.ResponseWriter, r *http.Request) {
	// Set content type for JSON responses.
	w.Header().Set("Content-Type", "application/json")

	// Only allow POST requests.
	if r.Method != http.MethodPost {
		writeJSONResponse(w, http.StatusMethodNotAllowed, Response{
			Status:  "error",
			Message: "method not allowed, use POST",
		})
		return
	}

	// Read the request body with a timeout context.
	ctx, cancel := context.WithTimeout(r.Context(), 5*time.Second)
	defer cancel()

	// Use a buffered reader to read the body.
	body, err := io.ReadAll(r.Body)
	if err != nil {
		writeJSONResponse(w, http.StatusBadRequest, Response{
			Status:  "error",
			Message: fmt.Sprintf("failed to read request body: %v", err),
		})
		return
	}

	// Check if the context was cancelled during reading.
	select {
	case <-ctx.Done():
		writeJSONResponse(w, http.StatusRequestTimeout, Response{
			Status:  "error",
			Message: "request timed out",
		})
